<template>
    <div class="layout-px-spacing">  
        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                            <li class="breadcrumb-item active" aria-current="page"><span>{{ header.toLowerCase() }}</span></li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>

        

        
        <div class="d-flex align-items-center me-4 mt-2 my-4 position-relative w-100">
            <!-- Centered Header -->
            <div class="flex-grow-1 text-center">
                <h5 class="m-0">{{ header }}</h5>
                <div class="d-flex justify-content-center align-items-center mt-2">
                    <global-search-field
                        v-model:filterValue="filter"
                    />
                </div>
            </div>
 
            <!-- Button on the right -->
            <div class="ms-auto" >
                                             <button 
                                class="btn btn-primary refresh-btn rounded-circle p-2 me-2 spin-animation" 
                                @click="getBinCards()" 
                                title="Refresh page"
                                :disabled="loading"
                                style="width: 2.5rem; height: 2.5rem;"
                            >
                            <span v-if="loading" v-html="loadingSpinner()">

                            </span>
                                <svg 
                                    xmlns="http://www.w3.org/2000/svg" 
                                    width="16" 
                                    height="16" 
                                    fill="currentColor" 
                                    class="bi bi-arrow-clockwise" 
                                    viewBox="0 0 16 16"
                                >
                                    <path fill-rule="evenodd" d="M8 3a5 5 0 1 0 4.546 2.914.5.5 0 0 1 .908-.417A6 6 0 1 1 8 2v1z"/>
                                    <path d="M8 4.466V.534a.25.25 0 0 1 .41-.192l2.36 1.966c.12.1.12.284 0 .384L8.41 4.658A.25.25 0 0 1 8 4.466z"/>
                                </svg>
                            </button>
                <button
                v-if="user_permissions.includes('can_create_bin_card')"
                class="btn btn-primary" @click="conversion_factor = !conversion_factor">
                   <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16"> <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/> <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/> </svg>
                </button>
            </div>
                 
        </div>

        <!-- loading spinner starts -->
        <div v-if="loading_spinner || loading" v-html="waitIndicator()"></div>
        <!-- Loading spinner ends -->

        <div class="my-4">
            <!-- item registration form starts -->
            <form v-if="conversion_factor" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="registerBinCard">
                <h5 class="text-center">REGISTER {{ header }} </h5>

                <div class="row mb-2">
                    <div class="col-md-4">
                        <label class=" form-label"> Name</label>
                        <input type="text" class="form-control" placeholder="Enter Name" v-model="name" required>
                    </div>
                    <div class="col-md-4">
                        <label class=" form-label">Description</label>
                        <input type="text" class="form-control" placeholder="Enter Description" v-model="description" required>
                    </div>

                    <div class="col-md-4">
                        <label class="form-label small">Unit</label>
                        <multiselect 
                            v-model="units"
                            :options="unitList"
                            placeholder="select unit"
                            label="short_name"
                            :searchable="true"        
                            :multiple="false"
                            :required="true"
                            :allow-empty="false"
                        ></multiselect>
                    </div>
                </div>
                <div class="text-center gap-2 justify-content-end">
                    <button type="button" class="btn btn-danger me-3" @click="conversion_factor = false; resetForm();">Cancel</button>
                    <button type="submit" class="btn btn-primary">Register</button>
                </div>
            </form>
            <!-- item registration form ends-->
        </div>


        <!-- Bin Cards List -->
        <div v-if="filteredBinCards.length === 0 && (!loading || !loading_spinner )" class="alert alert-light text-center">No {{ header }} records found</div>
        <div v-else  class="accordion accordion-flush" id="accordionFlushExample">
            <div  class="accordion-item" v-for="(binCard, index) in filteredBinCards" :key="binCard.id">
                <h2 class="accordion-header">
<button v-if="!loading"  class="accordion-button collapsed position-relative pe-5"
    type="button"
    data-bs-toggle="collapse"
    :data-bs-target="'#flush-collapse-' + binCard.id"
    aria-expanded="false"
    :aria-controls="'flush-collapse-' + binCard.id">

    {{ index + 1 }} : &nbsp;&nbsp; 
    {{ binCard.name }} &nbsp;&nbsp; 
    <span v-if="route.params.category_id == 5" >Return Amount :    <i class="text-danger"> {{ formatNumber(binCard.balance * (-1))}} </i>&nbsp;  </span> 
     <span v-else> Balance {{ formatNumber(binCard.balance)}} &nbsp;  </span> 
    {{ binCard.unit }} &nbsp;&nbsp; 
    {{ binCard.description }}

    <i><span class="position-absolute top-50 translate-middle-y fw-bold text-primary"
          style="right: 5rem;">
           <svg
                 v-if="user_permissions.includes('can_delete_bincard')"
                style="cursor: pointer;"
                xmlns="http://www.w3.org/2000/svg"
                                 width="26"
                                  height="26"                                 
                                   fill="currentColor"
                                    class="bi bi-trash text-danger me-2"
                                     @click="deleteStatement(binCard)"
                                     viewBox="0 0 16 16">
                                    <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
                                    <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"/>
                                </svg>
        {{ binCard.issuer ?? 'No Issuer' }}
    </span>
    </i>

</button>

                </h2>
                <div :id="'flush-collapse-' + binCard.id" class="accordion-collapse collapse" :data-bs-parent="'#accordionFlushExample'">
                    <div class="accordion-body">
                        <div class="d-flex justify-content-end mb-3">  
                            
                            <button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#add-item-modal" @click="openAddItemModal(binCard)" > 
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
                                    <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
                                    <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
                                </svg>
                            </button>
                            <button class="btn btn-success ms-2" @click="printAccountStatement(binCard) " v-if="category_id == 4">
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-printer" viewBox="0 0 16 16">
                                    <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1"/>
                                    <path d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1"/>
                                </svg>
                            </button>
                            <button class="btn btn-success ms-2" @click="printImprestReturn(binCard) " v-if="category_id == 5">
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-printer" viewBox="0 0 16 16">
                                    <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1"/>
                                    <path d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1"/>
                                </svg>
                            </button>
                        </div> 

                        <div class="panel p-0 mt-3">                            
                            <div class="custom-table table3 mt-3">
                                <v-client-table 
                                    :data="getTableData(binCard.items , binCard)" 
                                    :columns="category_id == 4 ? item_columns : item_columns_imprest" 
                                    :options="table_option">
                                    <template #actions="props">
                              
                                <a href="javascript:;" class="edit me-3" @click="openEditItemModal(props.row)" data-bs-toggle="modal" :data-bs-target="'#edit-conversion-factor-modal'" v-if="user_permissions.includes('can_edit_bin_card_items')">
                                    <svg
        xmlns="http://www.w3.org/2000/svg"
        width="24"
        height="24"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="1.5"
        stroke-linecap="round"
        stroke-linejoin="round"
        class="text-primary"
        style="cursor: pointer;"
        title="Edit Activity"
      >
        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path>
        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>
      </svg>
                                </a>
                                <a href="javascript:;" class="cancel" @click="deleteBinCardItem(props.row)" v-if="user_permissions.includes('can_delete_bin_card_items')">
                                    <span 
                                        v-if="deletingItemId === props.row.id"
                                        class="spinner-border spinner-border-sm text-danger" 
                                        role="status" 
                                        aria-hidden="true"
                                        style="width: 24px; height: 24px;"
                                    ></span>
                                    <svg
                                        v-else
                                        xmlns="http://www.w3.org/2000/svg"
                                        width="24"
                                        height="24"
                                        viewBox="0 0 24 24"
                                        fill="none"
                                        stroke="currentColor"
                                        stroke-width="1.5"
                                        stroke-linecap="round"
                                        stroke-linejoin="round"
                                        class="text-danger"
                                    >
                                        <polyline points="3 6 5 6 21 6"></polyline>
                                        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
                                    </svg>
                                </a>
                            </template>
                            <template #lpo_or_voucher="props">
                                <span
                                class="badge badge-primary "
                                style="cursor: pointer;"
                                data-bs-toggle="modal" 
                                data-bs-target="#transaction-record-modal"
                                @click="transaction=props.row;ref_no = props.row.lpo_or_voucher;getApproval()"
                                >
                                 {{ props.row.lpo_or_voucher }}
                                </span>
                            </template>
                                </v-client-table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
   

    <!-- add binCard item starts -->
    <div class="modal fade mymodal" id="add-item-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="itemModalLabel" aria-hidden="true">
        <div class="modal-dialog modal-xl">
            <div class="modal-content">
                <div class="modal-header">
                    <h1 class="modal-title fs-5" id="itemModalLabel">Add Transaction For {{ binCard?.name }}</h1>
                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closebinCardModal()" id="close_item"></button>
                </div>
                <form @submit.prevent="AddBinCardItem()">
                    <div class="modal-body">
                        <div class="row mb-3">
                            <div class="col-md-3">
                                <label for="quantity"> Ref No</label>
                                <input type="number" v-model="ref_no" class="form-control" placeholder="Enter Ref No" step="any" @change="getApproval()">
                            </div>
                            <div class="col-md-3">
                                <label for="date"> Date</label>
                                <input type="date" v-model="date" class="form-control" required >
                            </div>

                              <div class="col-md-3">
                        <label class="form-label small">Direction</label>
                        <multiselect 
                            v-model="direction"
                            :options="['DEBIT','CREDIT']"
                            placeholder="select Direction"
                            :searchable="true"        
                            :multiple="false"
                            :required="true"
                            :allow-empty="false"
                        ></multiselect>
                    </div>


                            <div class="col-md-3" v-if="direction === 'DEBIT'">
                                <label for="quantity"> Debit</label>
                                <input type="number" v-model="received" class="form-control" placeholder="Enter Debit Quantity" step="any" >
                            </div>
                            <div  class="col-md-3"  v-if="direction === 'CREDIT'">
                                <label for="quantity"> Credit</label>
                                <input type="number" v-model="issued" class="form-control" placeholder="Enter Credit Quantity" step="any" >
                            </div>
                            <div class="col-md-12">
                                <label for="remark"> Remark</label>
                                <input type="text" v-model="remark" class="form-control" placeholder="Enter Remark">
                            </div>
                        </div>
                        <div v-if="order">
    
                                <!-- tabulated data starts -->
                                              <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3 table-responsive">
<table class="table table-bordered table-striped">
      <thead >
        <tr>
          <th>Order</th>
          <th >Requester</th>
          <th>Date </th>
          <th>Purpose</th>
          <th>Chain</th>
          <th v-if="order.project">Project</th>
          <th v-if="order.vendor.name || order.beneficiary">
          <span
           v-if="order.beneficiary"
          >
           Beneficiary
          </span>
          <span v-else>
           Vendor
          </span>
          </th>
          <th>Status</th>
          <th   v-if="user_permissions.includes('can_print_lpo')">Action</th>
        </tr>
      </thead>
      <tbody>
        <tr >
          <td>{{ order.id }}</td>
          <td >{{ order.requester.name }}</td>
          <td>{{ formatDate(order.date) }}</td>
          <td>{{order?.requisition_type }}</td>
          <td>{{order?.approval_group }}</td>
          <td v-if="order.project">{{ order.project }}</td>
          <td v-if="order.vendor.name || order.beneficiary">{{ order.vendor.name }}</td>
          <td>
            <span class="badge inv-status" :class="'badge-' + order.status.color">
                                    {{ order.status.name }}
                                </span>
          </td>
          <td>
<router-link :to="`/approval-chain/${order.id}`"  class="btn btn-sm btn-primary text-nowrap">
  view Order
</router-link>
          </td>
        </tr>
    <tr v-if="order.description ">
      <td colspan="8">
        <b> Brief Description : </b>
        {{ order.description }}
      </td>
    </tr>
      <tr v-if="order.remark">
      <td colspan="8"> <b> Remark :  </b> {{ order.remark }}</td>
    </tr>
      </tbody>
    </table>

    <!-- approval items starts -->
                   <table class="table table-bordered table-striped">
      <thead >
        <tr>
          <th>ID</th>
          <th>Item</th>
          <th>Decription</th>
          <th>Quantity</th>
          <th>Unit</th>
          <th>Rate</th>
          <th>Total</th>
          <th>Receiver</th>
          <th>Actions</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="reqItem in order.items">
           <td>{{ reqItem.id }}</td>
          <td>{{ reqItem.requisition_items.description }}</td>
          <td>
               <router-link class="btn btn-outline-primary" :to="`/requisition-budget/${reqItem.requisition_items.item_id}`"  v-if ="item.requisition_type ==='budget' && !reqItem.requisition_items.asset_id">  
              View Budget
              </router-link>
              <span v-else> 
                <span >
                       {{ reqItem.requisition_items.remark }}
                </span>
              
              </span>
           </td>
          <td>{{ reqItem.quantity}}</td>
          <td>
            {{ reqItem.requisition_items.units }}
          </td>
          <td>
            {{  formatNumber(reqItem.requisition_items.rate) }}
          </td>
          <td>

            <span>
             {{ formatNumber(reqItem.requisition_items.quantity * reqItem.requisition_items.rate) }}
            </span>


          </td>
          <td>{{ reqItem?.requisition_items.vendor?.name ?? reqItem.requisition_items.beneficiary }}</td>
          <td>
                      <router-link  :to="`/assets/fuel-statement/${reqItem.requisition_items.asset_id}`"  v-if ="reqItem.requisition_items.asset_id" class="me-2">     
                            <button class="btn btn-outline-primary me-2">Diesel </button>
                      </router-link>  

                       <router-link  :to="`/requisition-budget/${reqItem.requisition_items.item_id}`"  v-if ="item.requisition_type ==='budget'">     
                            <button class="btn btn-outline-primary me-2">Budget</button>
                      </router-link>  
                        <router-link  :to="`/jobcard/${item.source_id}/${reqItem.requisition_items.asset_id}`"  v-if ="item.requisition_type ==='jobcard'" class="me-2">     
                            <button class="btn btn-outline-primary me-2">Jobcard</button>
                      </router-link>  

                      <router-link  :to="`/asset/bincards/${reqItem.requisition_items.asset_id}`"  v-if ="reqItem.requisition_items.asset_bincards_total > 0">     
                            <button class="btn btn-outline-dark me-2">Fuel Manager </button>
                      </router-link>  

                      <router-link  :to="`${reqItem.category.path}/${reqItem.requisition_items.category_ref_id}`"  v-if ="reqItem.category">     
                            <button class="btn btn-outline-dark me-2">{{ reqItem.category.name }} </button>
                      </router-link>  

          </td>
    </tr>
      </tbody>
    </table>
     <!-- approval items ends -->
    </div>
    </div>
    </div>
                                 <!-- tabulated data ends -->
                        </div>
                    </div>
                    <div class="modal-footer">
                        <button type="button" class="btn btn-danger" data-bs-dismiss="modal" @click="closebinCardModal()" id="close_item">Close</button>
                        <button class="btn btn-primary me-2 mt-1" :disabled="isSending | !direction">
                            <span v-if="isSending" v-html="loadingSpinner()"></span>
                            <span>Save</span>
                        </button>
                    </div>
                </form>
            </div>
        </div>
    </div>
    <!-- add binCard item ends -->

             <!-- Edit bin card item  modal starts -->
<div class="modal fade mymodal" id="edit-conversion-factor-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editConversionFactorModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editConversionFactorModalLabel">Edit Transaction</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closeEditModal()"></button>
      </div>
      <form @submit.prevent="updateBinCardItem(bin_card_item_id)">
        <div class="modal-body">
            <div class="row mb-3">
                <div class="col-md-3">
                                <label for="quantity"> Ref No</label>
                                <input type="number" v-model="ref_no" class="form-control" placeholder="Enter Ref No" step="any">
                 </div>

                       <div class="col-md-3">
                        <label class="form-label small">Direction</label>
                        <multiselect 
                            v-model="direction"
                            :options="['DEBIT','CREDIT']"
                            placeholder="select Direction"
                            :searchable="true"        
                            :multiple="false"
                            :required="true"
                            :allow-empty="false"
                        ></multiselect>
                    </div>
                <div class="col-md-3" >
                <label for="quantity"> Debit Quantity</label>
              <input type="number" v-model="received" class="form-control" placeholder="Enter Quantity" step="any" :disabled="direction ==='CREDIT'">
            </div>
            <div class="col-md-3">
                <label for="quantity"> Credit Quantity</label>
              <input type="number" v-model="issued" class="form-control" placeholder="Enter Quantity" step="any" :disabled="direction ==='DEBIT'">
            </div>
            <div class="col-md-12">
                                <label for="remark"> Remark</label>
                                <input type="text" v-model="remark" class="form-control" placeholder="Enter Remark">
                            </div>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="closeEditModal()" id="close_editing">Close</button>
          <button type="submit" class="btn btn-primary">
            <span v-if="loading_spinner" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Edit
          </button>
        </div>
      </form>
    </div>
  </div>
</div>
<!-- Edit bin card item modal ends -->
<!-- transaction record starts -->
     <div class="modal fade mymodal" id="transaction-record-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="itemModalLabel" aria-hidden="true">
        <div class="modal-dialog modal-xl">
            <div class="modal-content">
                <div class="modal-header">
                    <h1 class="modal-title fs-5" id="itemModalLabel">Transaction Record For  {{ transaction.description }}</h1>
                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closebinCardModal()" id="close_item"></button>
                </div>
             
                
                    <div class="modal-body">
                             <div v-if="fetching_record" v-html="waitIndicator()"></div>   
                             
                <div v-if="warning_message" class="alert alert-danger" role="alert">
                   {{ warning_message }}
                </div>

